def transform(grid):
    h, w = len(grid), len(grid[0])
    # Identify the diagonal direction from the nonzero cells, and learn the
    # repeating four-color sequence from their diagonal offsets.
    cells = [(r, c, grid[r][c])
             for r in range(h) for c in range(w) if grid[r][c]]
    down_right = sum(1 for r, c, _ in cells
                     if r > 0 and c > 0 and grid[r-1][c-1] != 0) >= sum(
                     1 for r, c, _ in cells
                     if r > 0 and c+1 < w and grid[r-1][c+1] != 0)

    colors = {}
    for r, c, v in cells:
        offset = (c-r) if down_right else (c+r)
        colors[offset % 4] = v

    # If multiple diagonals share a residue, prefer the color occurring most
    # often on that residue.
    counts = {}
    for r, c, v in cells:
        offset = (c-r) if down_right else (c+r)
        k = offset % 4
        counts.setdefault(k, {})
        counts[k][v] = counts[k].get(v, 0) + 1
    for k, hist in counts.items():
        colors[k] = max(hist, key=hist.get)

    return [[colors[((c-r) if down_right else (c+r)) % 4]
             for c in range(w)] for r in range(h)]
