def transform(grid):
    h, w = len(grid), len(grid[0])

    # Horizontal stripe pattern: copy the last complete stripe into blank rows
    # at the beginning, as in the demonstration.
    if all(len({v for v in row if v}) <= 1 for row in grid):
        row_colors = [next((v for v in row if v), 0) for row in grid]
        known = [i for i, v in enumerate(row_colors) if v]
        if known:
            for r in range(h):
                if row_colors[r] == 0:
                    prev = [i for i in known if i < r]
                    row_colors[r] = row_colors[prev[-1] if prev else known[-1]]
            return [[row_colors[r]] * w for r in range(h)]

    # Diagonal strands specify colors by their column-minus-row offset.
    by_offset = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v:
                k = (c - r) % 4
                by_offset.setdefault(k, {})
                by_offset[k][v] = by_offset[k].get(v, 0) + 1

    palette = {k: max(hist, key=hist.get) for k, hist in by_offset.items()}
    return [[palette[(c - r) % 4] for c in range(w)] for r in range(h)]
